import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";

test.describe("MCP diagnostic events", () => {
  test.describe.configure({ timeout: 180_000 });

  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Direct MCP success shows tool event and opens details panel", async ({ inspectorPage }) => {
    await flows.mcp.triggerDirectMcpSuccessAndAssertEvent(inspectorPage);
    await flows.mcp.openMcpToolEventDetailsAndAssert(inspectorPage);
  });

  test("Context7 lookup emits MCP tool event in log", async ({ inspectorPage }) => {
    await flows.mcp.triggerContext7LookupAndAssertEvent(inspectorPage);
  });

  test("DeepWiki direct MCP emits ask_question tool event", async ({ inspectorPage }) => {
    await flows.mcp.triggerDeepWikiDirectMcpAndAssertEvent(inspectorPage);
  });
});
